//! Memoization caches whose shape is picked by the key type.
//!
//! A cache hit should cost as little as the key allows:
//!
//! - [`DenseCache`] for index keys (generated by [`newtype_index!`](crate::newtype_index)): one
//!   lazily allocated slot per index, so a lookup is an array access with no hashing.
//! - [`MapCache`] for arbitrary hashable keys, with the `FxHash` hasher.
//! - [`UnitCache`] for `()`: a single slot.
//!
//! Values are `Copy`, so a hit never clones or bumps a reference count. Large results belong in
//! an arena, and the cache stores the `&'arena T`.
//!
//! [`Cache<K, V>`] names the cache chosen for `K` through [`CacheKey`]:
//!
//! ```
//! use vulcan::cache::{Cache, QueryCache};
//!
//! vulcan::newtype_index! {
//!     /// Identifies a function.
//!     pub struct FnId;
//! }
//!
//! let costs: Cache<FnId, u64> = Cache::<FnId, u64>::with_len(1024);
//! let id = FnId::from_u32(7);
//! assert_eq!(costs.get_or_insert_with(id, || 42), 42);
//! assert_eq!(costs.get(id), Some(42));
//! ```

use crate::index::Idx;
use parking_lot::RwLock;
use rustc_hash::{FxBuildHasher, FxHashMap};
use std::{hash::Hash, sync::OnceLock};

/// A thread-safe memoization cache from `K` to `V`.
pub trait QueryCache<K, V: Copy> {
    /// Creates an empty cache. `len` is the number of distinct keys for dense caches and a
    /// capacity hint otherwise.
    fn with_len(len: usize) -> Self;

    /// Returns the cached value for `key`.
    fn get(&self, key: K) -> Option<V>;

    /// Returns the cached value for `key`, computing and storing it with `f` on a miss.
    fn get_or_insert_with(&self, key: K, f: impl FnOnce() -> V) -> V;
}

/// Selects the cheapest cache for a key type.
pub trait CacheKey: Copy {
    /// The cache used for this key type.
    type Cache<V: Copy>: QueryCache<Self, V>;
}

/// The cache selected for key type `K`.
pub type Cache<K, V> = <K as CacheKey>::Cache<V>;

/// The per-index slots of a [`DenseCache`].
type Slots<V> = Box<[OnceLock<V>]>;

/// Ties a cache to its key type without storing a key.
type KeyMarker<K> = std::marker::PhantomData<fn() -> K>;

/// One slot per index, allocated on first use.
///
/// Concurrent misses on the same key run `f` once: other threads wait for the first result.
/// Keys at or beyond `len` are computed but not cached.
#[derive(Debug)]
pub struct DenseCache<K, V> {
    len: usize,
    slots: OnceLock<Slots<V>>,
    _key: KeyMarker<K>,
}

impl<K: Idx, V: Copy> QueryCache<K, V> for DenseCache<K, V> {
    fn with_len(len: usize) -> Self {
        Self { len, slots: OnceLock::new(), _key: std::marker::PhantomData }
    }

    #[inline]
    fn get(&self, key: K) -> Option<V> {
        self.slots.get()?.get(key.index())?.get().copied()
    }

    #[inline]
    fn get_or_insert_with(&self, key: K, f: impl FnOnce() -> V) -> V {
        let slots = self.slots.get_or_init(|| (0..self.len).map(|_| OnceLock::new()).collect());
        match slots.get(key.index()) {
            Some(slot) => *slot.get_or_init(f),
            None => f(),
        }
    }
}

/// A hash map behind a read-write lock.
///
/// Hits take the read lock only. On a concurrent miss `f` may run on several threads; the first
/// value stored wins, so `f` must be deterministic.
#[derive(Debug)]
pub struct MapCache<K, V> {
    map: RwLock<FxHashMap<K, V>>,
}

impl<K: Hash + Eq, V: Copy> QueryCache<K, V> for MapCache<K, V> {
    fn with_len(len: usize) -> Self {
        Self { map: RwLock::new(FxHashMap::with_capacity_and_hasher(len, FxBuildHasher)) }
    }

    #[inline]
    fn get(&self, key: K) -> Option<V> {
        self.map.read().get(&key).copied()
    }

    fn get_or_insert_with(&self, key: K, f: impl FnOnce() -> V) -> V {
        if let Some(&value) = self.map.read().get(&key) {
            return value;
        }
        // Computed outside the lock, so a slow `f` never blocks readers.
        let value = f();
        *self.map.write().entry(key).or_insert(value)
    }
}

/// A single slot, for queries without arguments.
#[derive(Debug)]
pub struct UnitCache<V> {
    slot: OnceLock<V>,
}

impl<V: Copy> QueryCache<(), V> for UnitCache<V> {
    fn with_len(_len: usize) -> Self {
        Self { slot: OnceLock::new() }
    }

    #[inline]
    fn get(&self, (): ()) -> Option<V> {
        self.slot.get().copied()
    }

    #[inline]
    fn get_or_insert_with(&self, (): (), f: impl FnOnce() -> V) -> V {
        *self.slot.get_or_init(f)
    }
}

impl CacheKey for () {
    type Cache<V: Copy> = UnitCache<V>;
}

macro_rules! map_keys {
    ($($ty:ty),*) => {$(
        impl CacheKey for $ty {
            type Cache<V: Copy> = MapCache<Self, V>;
        }
    )*};
}

map_keys!(bool, char, u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);

impl<A: Hash + Eq + Copy, B: Hash + Eq + Copy> CacheKey for (A, B) {
    type Cache<V: Copy> = MapCache<Self, V>;
}

impl<T: ?Sized + Hash + Eq> CacheKey for &'static T {
    type Cache<V: Copy> = MapCache<Self, V>;
}

#[cfg(test)]
mod tests {
    use super::*;

    crate::newtype_index! {
        struct NodeId;
    }

    #[test]
    fn dense_cache_computes_once_and_skips_out_of_range() {
        let cache: Cache<NodeId, u32> = Cache::<NodeId, u32>::with_len(4);
        let id = NodeId::from_u32(2);
        assert_eq!(cache.get(id), None);
        assert_eq!(cache.get_or_insert_with(id, || 10), 10);
        assert_eq!(cache.get_or_insert_with(id, || 99), 10, "second call must hit");
        let far = NodeId::from_u32(100);
        assert_eq!(cache.get_or_insert_with(far, || 5), 5);
        assert_eq!(cache.get(far), None, "out-of-range keys are not cached");
    }

    #[test]
    fn map_and_unit_caches() {
        type PairCache = Cache<(u32, u32), &'static str>;
        let map = PairCache::with_len(8);
        assert_eq!(map.get_or_insert_with((1, 2), || "a"), "a");
        assert_eq!(map.get_or_insert_with((1, 2), || "b"), "a");
        assert_eq!(map.get((3, 4)), None);

        let unit: Cache<(), u8> = Cache::<(), u8>::with_len(0);
        assert_eq!(unit.get_or_insert_with((), || 1), 1);
        assert_eq!(unit.get(()), Some(1));
    }
}
